    for g in friends[i + 1:]:
        solver.add(Implies(And(met[f], met[g]), pos[f] != pos[g]))

for f in friends:
    locf = info[f]['loc']
    solver.add(Implies(
        And(met[f], pos[f] == 0),
        start[f] >= 540 + travel['Bayview'][locf]
    ))

for f in friends:
    for g in friends:
        if f == g:
            continue
        locf = info[f]['loc']
        locg = info[g]['loc']
        solver.add(Implies(
            And(met[f], met[g], pos[f] < pos[g]),
            start[g] >= end[f] + travel[locf][locg]
        ))

solver.check()
