            'friend': f,
            'loc': info[f]['loc'],
            'pos': model.eval(pos[f], model_completion=True).as_long(),
            'start': model.eval(start[f], model_completion=True).as_long(),
            'end': model.eval(end[f], model_completion=True).as_long()
        })

events.sort(key=lambda e: e['pos'])

itinerary = ["You start at Bayview at " + fmt(540) + "."]
