    solver.add(Implies(met[i], start[i] + f['dur'] <= f['close']))

    in_edges = [x[(S, i)]] + [x[(j, i)] for j in range(n) if j != i]
    out_edges = [x[(i, T)]] + [x[(i, j)] for j in range(n) if j != i]
    in_sum = Sum([If(e, 1, 0) for e in in_edges])
    out_sum = Sum([If(e, 1, 0) for e in out_edges])
    solver.add(in_sum == If(met[i], 1, 0))
    solver.add(out_sum == If(met[i], 1, 0))

