def fmt(t):
    t = int(t) % (24 * 60)
    h = t // 60
    minute = t % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{minute:02d}{suffix}"

